def build_meditation_sessions():
    """Convert compact data to full session objects.

    Catalog fields stay as authored. Audio availability is then checked
    against ``meditation audios/``. Provisional attributes, when a session
    has been reviewed in ``metadata.py``, are merged beside the catalog.
    Duration comes from the recording, not a blanket 10-minute default.
    """
    from meditation.audio import measure_duration_seconds, resolve_audio_file
    from meditation.metadata import (
        METADATA_STATUS_UNREVIEWED,
        SESSION_METADATA,
        friction_for_duration,
    )

    sessions = {}

    for session_id, data in SESSIONS_DATA.items():
        tab, title, description, category, catalog_has_audio = data
        order = int(session_id) % 100 if int(session_id) % 100 != 0 else 10
        audio_path = resolve_audio_file(session_id) if catalog_has_audio else None
        has_audio = audio_path is not None
        duration_seconds = measure_duration_seconds(audio_path) if audio_path else None
        meta = SESSION_METADATA.get(session_id) or {}
        reviewed = bool(meta)

        sessions[session_id] = {
            "id": session_id,
            "tab": tab,
            "title": title,
            "description": description,
            "audio_file": f"{session_id}.mp3" if has_audio else None,
            "duration_seconds": duration_seconds,
            "duration_source": "mp3_bitrate_estimate" if duration_seconds else None,
            "category": category,
            "order": order,
            "catalog_has_audio": catalog_has_audio,
            "has_audio": has_audio,
            "metadata_status": meta.get("metadata_status", METADATA_STATUS_UNREVIEWED),
            "metadata_basis": meta.get("metadata_basis"),
            "pad_coordinates": meta.get("pad_coordinates") if reviewed else None,
            "target_latent_states": list(meta.get("target_latent_states") or []),
            "friction_level": friction_for_duration(duration_seconds) if reviewed else None,
            "required_cognitive_load": meta.get("required_cognitive_load") if reviewed else None,
            "technique": meta.get("technique") if reviewed else None,
            "tags": list(meta.get("tags") or []),
            "languages": list(meta.get("languages") or []),
            "user_reason": meta.get("user_reason") if reviewed else None,
        }

    return sessions


# Build the full sessions dictionary
MEDITATION_SESSIONS = build_meditation_sessions()


def get_all_sessions():
    """Get all meditation sessions"""
    return list(MEDITATION_SESSIONS.values())


def get_session_by_id(session_id: str):
    """Get a specific meditation session by ID"""
    return MEDITATION_SESSIONS.get(session_id)


def get_sessions_by_tab(tab: int):
    """Get all sessions for a specific tab"""
    return [s for s in MEDITATION_SESSIONS.values() if s["tab"] == tab]


def get_sessions_by_category(category: str):
    """Get all sessions for a specific category"""
    return [s for s in MEDITATION_SESSIONS.values() if s["category"] == category]
